import { code } from '../../code.ts';
import type { IosValues } from '../values.ts';

// The path of the file in plugins/ios.
export const path = (v: IosValues) => `${v.id}/include/${v.product}/${v.product}.h`;

export default (v: IosValues) => code`
// clang-format off
// Generated by plugins/tools/generate.ts from plugins/plugins/${v.id}/plugin.json; do not edit.
#import <Foundation/Foundation.h>

NS_ASSUME_NONNULL_BEGIN

/** Error domain of errors returned by \`+[${v.className} registerPluginWithError:]\`. */
FOUNDATION_EXPORT NSErrorDomain const ${v.className}ErrorDomain;

/**
 Registers the ${v.displayName} plugin with MapLibre.

 Call it before creating a map that loads a style using the plugin's layer types.
 Registering again succeeds.
 */
NS_SWIFT_NAME(${v.swiftName})
@interface ${v.className} : NSObject

/**
 Registers the plugin's layer types.

 @param error Set to the reason when registration fails.
 @return \`YES\` when the plugin is registered.
 */
+ (BOOL)registerPluginWithError:(NSError *_Nullable *_Nullable)error NS_SWIFT_NAME(registerPlugin());

- (instancetype)init NS_UNAVAILABLE;

@end

NS_ASSUME_NONNULL_END
`;
